# Tests dot-source the production functions. No host construction or native engine call.
# Expected FFD-CANON-1 bytes below were independently assembled, not generated by the probe.
function Read-FfdCanonical([byte[]] $Bytes) {
    if ($Bytes.Length -gt 1MB -or $Bytes.Length -lt 12) { Stop-Ffd 'codec-size' }
    $prefix=[Text.Encoding]::ASCII.GetBytes("FFD-CANON-1`0")
    for ($i=0;$i -lt $prefix.Length;$i++) { if ($Bytes[$i] -ne $prefix[$i]) { Stop-Ffd 'codec-prefix' } }
    $s=[IO.MemoryStream]::new($Bytes,$false); $s.Position=$prefix.Length
    $r=[IO.BinaryReader]::new($s,$script:FfdUtf8)
    try {
        $value=Read-FfdCanonicalValue $r 0
        if ($s.Position -ne $s.Length) { Stop-Ffd 'codec-trailing' }
        return ,$value
    } finally { $r.Dispose(); $s.Dispose() }
}
function Read-FfdCanonicalValue($Reader, [int] $Depth) {
    if ($Depth -gt 1024) { Stop-Ffd 'codec-depth' }
    $tag=$Reader.ReadByte()
    switch ($tag) {
        0 { return @{tag='null';value=$null} }
        1 { return @{tag='bool';value=$false} }
        2 { return @{tag='bool';value=$true} }
        3 { return @{tag='int64';value=$Reader.ReadInt64()} }
        4 {
            $bits=$Reader.ReadUInt32(); $f=[BitConverter]::UInt32BitsToSingle($bits)
            if (-not [single]::IsFinite($f)) { Stop-Ffd 'codec-nonfinite' }
            return @{tag='float32';bits=('{0:x8}' -f $bits);value=$f}
        }
        5 {
            $bits=$Reader.ReadUInt64(); $f=[BitConverter]::UInt64BitsToDouble($bits)
            if (-not [double]::IsFinite($f)) { Stop-Ffd 'codec-nonfinite' }
            return @{tag='float64';bits=('{0:x16}' -f $bits);value=$f}
        }
        6 {
            $n=$Reader.ReadUInt32()
            if ($n -gt 1MB -or $n -gt $Reader.BaseStream.Length-$Reader.BaseStream.Position) { Stop-Ffd 'codec-length' }
            $bytes=$Reader.ReadBytes([int]$n)
            return @{tag='string';value=$script:FfdUtf8.GetString($bytes)}
        }
        7 {
            $n=$Reader.ReadUInt32(); if ($n -gt 1MB) { Stop-Ffd 'codec-length' }
            $array=[Collections.Generic.List[object]]::new()
            for ($i=0;$i -lt $n;$i++) { $array.Add((Read-FfdCanonicalValue $Reader ($Depth+1))) }
            return @{tag='array';value=$array.ToArray()}
        }
        8 {
            $n=$Reader.ReadUInt32(); if ($n -gt 1MB) { Stop-Ffd 'codec-length' }
            $record=[Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal); $prior=$null
            for ($i=0;$i -lt $n;$i++) {
                $key=Read-FfdCanonicalValue $Reader ($Depth+1)
                if ($key.tag -cne 'string' -or $key.value -cnotmatch '^[\x20-\x7e]+$' -or
                    ($null -ne $prior -and [StringComparer]::Ordinal.Compare($prior,$key.value) -ge 0)) { Stop-Ffd 'codec-record-order' }
                $record.Add($key.value,(Read-FfdCanonicalValue $Reader ($Depth+1))); $prior=$key.value
            }
            return @{tag='record';value=$record}
        }
        9 {
            $name=Read-FfdCanonicalValue $Reader ($Depth+1)
            if ($name.tag -cne 'string' -or $name.value -cnotmatch '^[A-Za-z0-9_.+]+$') { Stop-Ffd 'codec-enum' }
            return @{tag='enum';type=$name.value;value=$Reader.ReadInt64()}
        }
        default { Stop-Ffd 'codec-tag' }
    }
}
function Assert-FfdMutation($Before,$After,[string] $Field) {
    if($Before.tag -cne 'record' -or $After.tag -cne 'record' -or $Before.value.Count -ne $After.value.Count){Stop-Ffd 'mutation-record'}
    foreach($key in $Before.value.Keys){
        if(-not $After.value.ContainsKey($key)){Stop-Ffd 'mutation-field'}
        $a=$Before.value[$key] | ConvertTo-Json -Depth 64 -Compress
        $b=$After.value[$key] | ConvertTo-Json -Depth 64 -Compress
        if(($key -ceq $Field -and $a -ceq $b) -or ($key -cne $Field -and $a -cne $b)){Stop-Ffd 'mutation-value'}
    }
}
function Invoke-FfdTest($State,[string] $Name,[string] $Expected,[scriptblock] $Action) {
    $got=''; try { & $Action } catch { $got=Get-FfdCode $_ }
    $pass=$got -ceq $Expected
    $State.Add([ordered]@{name=$Name;passed=$pass;expected=$Expected;actual=$got})
    if (-not $pass) { Stop-Ffd 'contract-test-failed' }
}
function New-FfdTestEvents {
    $items=@(
