        @{event='phase-start';data=@{phase='read'}},
        @{event='input-config';data=@{synthetic=$true}},
        @{event='phase-start';data=@{phase='constructor'}},
        @{event='phase-start';data=@{phase='render'}},
        @{event='metrics-snapshot';data=@{synthetic=$true}},
        @{event='phase-start';data=@{phase='verification'}},
        @{event='result';data=@{status='measured'}},
        @{event='metrics-final';data=@{status='measured'}},
        @{event='phase-start';data=@{phase='dispose'}},
        @{event='session-end';data=@{status='completed';reportingMs=0}})
    for ($i=0;$i -lt $items.Count;$i++) {
        [ordered]@{schema='headless-events-v1';event=$items[$i].event;session='synthetic';sequence=$i;data=$items[$i].data}
    }
}
function Write-FfdTestEvents([string] $Path,$Events) {
    $lines=@($Events | ForEach-Object { $_ | ConvertTo-Json -Depth 30 -Compress }) -join "`n"
