        @{name='bytes';mutate={param($a)$a[5].digest.bytes=101}},
        @{name='cardinality';mutate={param($a)$a[5].digest.cardinalities.boxes=10}},
        @{name='incomplete';mutate={param($a)$a[5].status='incomplete'}})){
        Invoke-FfdTest $Checks "aggregate-$($case.name)" 'sample-homogeneity' {$a=Copy-FfdTestValue $samples;$null=& $case.mutate $a;$null=Get-FfdAggregate $a}
    }
    # Exercise the same whole-sample gate used by the real six-process loop.
    $validEvents=@(New-FfdTestEvents)
    foreach($e in $validEvents){$e.session='warmup'}
    $validEvents[2].data=@{inputSha256=$valid.inputSha256;sourceCommit=$valid.sourceCommit;sourceTree=$valid.sourceTree;files=(Copy-FfdTestValue $valid.files);configuration=(Copy-FfdTestValue $valid.configuration)}
    $snapshotMetrics=@{};foreach($key in @('constructorMs','firstRenderWallMs','styleResolutionMs','layoutInteropMs','layoutProjectionMs','displayListBuildMs','renderMs','readDecodeMs')){$snapshotMetrics[$key]=$valid.metrics[$key]}
    $validEvents[5].data=@{counts=(Copy-FfdTestValue $valid.counts);metrics=$snapshotMetrics;timestampTicks=@(0,0,0,0,0)}
    $eventsPath=Join-Path $Private 'synthetic-sample.events.jsonl'
    $record=@{status='completed';started=$true;exitCode=0;timedOut=$false;logsComplete=$true;termination='not-needed';stderrBytes=0}
    Write-FfdTestEvents $eventsPath $validEvents
    Invoke-FfdTest $Checks 'sample-whole-gate-positive' '' {$null=Read-FfdSample $record $eventsPath $resultPath 'warmup' $manifest}
    Invoke-FfdTest $Checks 'sample-empty-stdout' 'file-shape' {
        try{[IO.File]::WriteAllBytes($eventsPath,[byte[]]::new(0));$null=Read-FfdSample $record $eventsPath $resultPath 'warmup' $manifest}finally{Write-FfdTestEvents $eventsPath $validEvents}
    }
    Invoke-FfdTest $Checks 'sample-truncated-stdout' 'event-truncated' {
        $bytes=[IO.File]::ReadAllBytes($eventsPath)
        try{[IO.File]::WriteAllBytes($eventsPath,$bytes[0..($bytes.Length-2)]);$null=Read-FfdSample $record $eventsPath $resultPath 'warmup' $manifest}finally{Write-FfdTestEvents $eventsPath $validEvents}
    }
    foreach($case in @(
        @{name='end-missing';code='event-incomplete';mutate={param($e)$e.RemoveAt($e.Count-1)}},
        @{name='end-duplicate';code='event-order';mutate={param($e)$e.Add((Copy-FfdTestValue $e[$e.Count-1]))}},
        @{name='error-before-final';code='event-error';mutate={param($e)$e.Insert(8,@{schema='headless-events-v1';event='error';session='warmup';sequence=0;data=@{code='synthetic-error';exceptionType='IOException'}})}},
        @{name='dispose-after-final';code='event-error';mutate={param($e)$e.Insert(10,@{schema='headless-events-v1';event='error';session='warmup';sequence=0;data=@{code='dispose-failure';exceptionType='IOException'}})}},
        @{name='error-after-end';code='event-error';mutate={param($e)$e.Add(@{schema='headless-events-v1';event='error';session='warmup';sequence=0;data=@{code='late-error';exceptionType='IOException'}})}},
        @{name='input-identity';code='event-result-identity';mutate={param($e)$e[2].data.sourceCommit='0'*40}},
        @{name='snapshot-metric';code='event-result-metric';mutate={param($e)$e[5].data.metrics.constructorMs=1}},
        @{name='snapshot-count';code='event-result-count';mutate={param($e)$e[5].data.counts.RenderCalls=2}},
        @{name='config-extra';code='schema-fields';mutate={param($e)$e[2].data.configuration.extra=1}}
    )){
        Invoke-FfdTest $Checks "sample-$($case.name)" $case.code {
            $e=[Collections.Generic.List[object]]::new();foreach($entry in $validEvents){$e.Add((Copy-FfdTestValue $entry))}
            $null=& $case.mutate $e;for($i=0;$i -lt $e.Count;$i++){$e[$i].sequence=$i}
            # The result file remains fully valid in all of these cases.
            try{Write-FfdTestEvents $eventsPath $e;$null=Read-FfdSample $record $eventsPath $resultPath 'warmup' $manifest}finally{Write-FfdTestEvents $eventsPath $validEvents}
        }
    }
    $finishClock=@{tick=100000L;local=0.0};$finishTick={$finishClock.tick}.GetNewClosure();$finishLocal={$finishClock.local}.GetNewClosure()
    $finishAnchor=@{schema='headless-budget-anchor-v1';runId='1';runAttempt='1';jobId='job';tickCount64=100000L;utc='unused'}
    $finishBudget=New-FfdBudget $finishAnchor '1' '1' 'job' $finishTick $finishLocal
    Start-FfdPhase $finishBudget 'finalize' 15 75
    Invoke-FfdTest $Checks 'finalize-local-only-positive' '' {
        $summary=@{status='incomplete';phase='finalize';statistics=$null;upload='not-observed-by-producer'}
        Complete-FfdSummary $summary $samples $finishBudget
        if($summary.status -cne 'completed' -or $summary.upload -cne 'not-observed-by-producer'){Stop-Ffd 'test-completion-scope'}
    }
    Invoke-FfdTest $Checks 'finalize-cut-before-phase' 'finalization-phase' {
        $summary=@{status='incomplete';phase='samples';statistics=$null;upload='not-observed-by-producer'}
        $finishBudget.phase='samples'
        try{Complete-FfdSummary $summary $samples $finishBudget}finally{if($summary.status -cne 'incomplete' -or $null -ne $summary.statistics){Stop-Ffd 'test-premature-completion'};$finishBudget.phase='finalize'}
    }
    Invoke-FfdTest $Checks 'finalize-timeout-no-promotion' 'phase-timeout' {
        $summary=@{status='incomplete';phase='finalize';statistics=$null;upload='not-observed-by-producer'};$finishClock.local=15001
        try{Complete-FfdSummary $summary $samples $finishBudget}finally{if($summary.status -cne 'incomplete' -or $null -ne $summary.statistics){Stop-Ffd 'test-premature-completion'};$finishClock.local=0}
    }
    Invoke-FfdTest $Checks 'finalize-missing-sample-no-promotion' 'sample-set' {
        $summary=@{status='incomplete';phase='finalize';statistics=$null;upload='not-observed-by-producer'}
        try{Complete-FfdSummary $summary $samples[0..4] $finishBudget}finally{if($summary.status -cne 'incomplete' -or $null -ne $summary.statistics){Stop-Ffd 'test-premature-completion'}}
    }
    $io=New-FfdIoFixture (Join-Path $Private 'contract-io')
    Invoke-FfdTest $Checks 'source-io-positive' '' {Assert-FfdSource $io.source $io.root $Budget}
    foreach($case in @(
        @{name='commit';code='source-identity';mutate={param($s)$s.commit='0'*40}},
        @{name='inventory-count';code='source-inventory-count';mutate={param($s)$s.inventory=@($s.inventory[1..($s.inventory.Count-1)])}},
        @{name='inventory-mode';code='source-inventory';mutate={param($s)$s.inventory[0].mode='100755'}},
        @{name='inventory-blob';code='source-diagnostics';mutate={param($s)$s.inventory[0].blob='0'*40}},
        @{name='history-name';code='source-history';mutate={param($s)$s.identities[0].name='wrong'}},
        @{name='diagnostics-path';code='source-diagnostics';mutate={param($s)$s.diagnostics[0].path='extra.cs'}},
        @{name='diagnostics-before';code='source-diagnostics';mutate={param($s)$s.diagnostics[4].beforeSha256='wrong'}},
        @{name='control';code='source-control';mutate={param($s)$s.controls[0].blob='0'*40}},
        @{name='path-traversal';code='source-path';mutate={param($s)$s.files[0].path='../escape'}},
        @{name='file-blob';code='source-inventory';mutate={param($s)$s.files[0].blob='0'*40}},
        @{name='pin';code='source-pin';mutate={param($s)$s.files[0].blobSha256='0'*64}},
        @{name='file-hash';code='source-rehash';mutate={param($s)$s.files[0].physicalSha256='0'*64}},
        @{name='file-size';code='source-rehash';mutate={param($s)$s.files[0].bytes=1}}
    )){
        Assert-FfdDeadline $Budget
        Invoke-FfdTest $Checks "source-$($case.name)" $case.code {$s=Copy-FfdTestValue $io.source;$null=& $case.mutate $s;Assert-FfdSource $s $io.root $Budget}
    }
    Invoke-FfdTest $Checks 'source-physical-mutation' 'source-rehash' {
        $path=Join-Path $io.root $io.source.files[0].path;$bytes=[IO.File]::ReadAllBytes($path)
        try{[IO.File]::WriteAllText($path,'changed',$script:FfdUtf8);Assert-FfdSource $io.source $io.root $Budget}finally{[IO.File]::WriteAllBytes($path,$bytes)}
    }
    Invoke-FfdTest $Checks 'ct-io-positive' '' {$null=Assert-FfdCt $io.root $Budget}
    foreach($case in @(
        @{name='status';code='ct-incomplete';mutate={param($m)$m.status='failed'}},
        @{name='sdk';code='ct-incomplete';mutate={param($m)$m.toolchain.dotnetSdk='other'}},
        @{name='stage-count';code='ct-stage-set';mutate={param($m)$m.stageFiles=@($m.stageFiles[1..23])}},
        @{name='stage-order';code='ct-stage-set';mutate={param($m)$m.stageFiles[0]='stage-toolchain.json'}},
        @{name='source';code='source-identity';mutate={param($m)$m.source.commit='0'*40}},
        @{name='binary-set';code='ct-binary-set';mutate={param($m)$m.build.exportCandidate=@()}},
        @{name='binary-hash';code='ct-binary-hash';mutate={param($m)$m.build.exportCandidate[0].sha256='0'*64}},
        @{name='native-hash';code='ct-loaded-native';mutate={param($m)$m.build.native.sha256='0'*64}}
    )){
        Assert-FfdDeadline $Budget
        Invoke-FfdTest $Checks "ct-$($case.name)" $case.code {
            $m=Copy-FfdTestValue $io.manifest;$null=& $case.mutate $m
            try{Write-FfdJson "$($io.evidence)/manifest.json" $m;$null=Assert-FfdCt $io.root $Budget}finally{Write-FfdJson "$($io.evidence)/manifest.json" $io.manifest}
        }
    }
    foreach($case in @(
        @{name='stage-failed';code='ct-stage-incomplete';mutate={param($s)$s.status='failed'}},
        @{name='source-pipe-open';code='ct-process-incomplete';mutate={param($s)$s.commands[0].complete=$false}},
        @{name='source-tests-failed';code='source-tests-incomplete';mutate={param($s)$s.details.tests.status='failed'}},
        @{name='source-tests-case';code='source-tests-incomplete';mutate={param($s)$s.details.tests.cases[0].passed=$false}}
    )){
        Invoke-FfdTest $Checks "ct-$($case.name)" $case.code {
            $path="$($io.evidence)/stage-source.json";$original=Read-FfdJson $path;$changed=Copy-FfdTestValue $original;$null=& $case.mutate $changed
            try{Write-FfdJson $path $changed;$null=Assert-FfdCt $io.root $Budget}finally{Write-FfdJson $path $original}
        }
    }
    Invoke-FfdTest $Checks 'ct-loaded-assembly-mismatch' 'ct-loaded-assembly' {
        $e=Copy-FfdTestValue $io.export;$e.assemblies[0].sha256='0'*64
        try{Write-FfdJson "$($io.evidence)/export-candidate.json" $e;$null=Assert-FfdCt $io.root $Budget}finally{Write-FfdJson "$($io.evidence)/export-candidate.json" $io.export}
    }
    Invoke-FfdTest $Checks 'ct-physical-binary-mismatch' 'ct-binary-hash' {
        $path=Join-Path $io.root 'artifacts/validator-metrics/export-candidate-bin/AetherUI.Core.dll';$bytes=[IO.File]::ReadAllBytes($path)
        try{[IO.File]::WriteAllText($path,'changed',$script:FfdUtf8);$null=Assert-FfdCt $io.root $Budget}finally{[IO.File]::WriteAllBytes($path,$bytes)}
    }
    Invoke-FfdTest $Checks 'dependencies-io-positive' '' {$null=Assert-FfdDependencies $io.project $io.output $io.hashes $Budget}
    foreach($case in @(
        @{name='package';code='dependency-package-or-project';mutate={param($a)$a.libraries['Package/1.0.0']=@{type='package'}}},
        @{name='framework';code='dependency-framework';mutate={param($a)$a.project.frameworks.net10.frameworkReferences['Microsoft.WindowsDesktop.App']=@{}}},
        @{name='project';code='dependency-project';mutate={param($a)$a.project.restore.frameworks.net10.projectReferences['another.csproj']=@{}}},
        @{name='direct-package';code='dependency-package';mutate={param($a)$a.project.frameworks.net10.dependencies=@{Other=@{}}}}
    )){
        Invoke-FfdTest $Checks "dependencies-$($case.name)" $case.code {
            $a=Copy-FfdTestValue $io.assets;$null=& $case.mutate $a
            try{Write-FfdJson "$($io.project)/obj/project.assets.json" $a;$null=Assert-FfdDependencies $io.project $io.output $io.hashes $Budget}finally{Write-FfdJson "$($io.project)/obj/project.assets.json" $io.assets}
        }
    }
    Invoke-FfdTest $Checks 'dependencies-runtime' 'runtime-framework' {
        $r=Copy-FfdTestValue $io.runtime;$r.runtimeOptions.framework.name='Microsoft.WindowsDesktop.App'
        try{Write-FfdJson "$($io.output)/AetherUI.Validator.HeadlessDiagnostics.runtimeconfig.json" $r;$null=Assert-FfdDependencies $io.project $io.output $io.hashes $Budget}finally{Write-FfdJson "$($io.output)/AetherUI.Validator.HeadlessDiagnostics.runtimeconfig.json" $io.runtime}
    }
    Invoke-FfdTest $Checks 'dependencies-closure' 'dependency-closure' {
        $d=Copy-FfdTestValue $io.deps;$d.libraries['Unapproved/1.0.0']=@{type='reference'}
        try{Write-FfdJson "$($io.output)/AetherUI.Validator.HeadlessDiagnostics.deps.json" $d;$null=Assert-FfdDependencies $io.project $io.output $io.hashes $Budget}finally{Write-FfdJson "$($io.output)/AetherUI.Validator.HeadlessDiagnostics.deps.json" $io.deps}
    }
    Invoke-FfdTest $Checks 'dependencies-copy-mismatch' 'copied-binary-identity' {
        $path=Join-Path $io.output 'AetherUI.Core.dll';$bytes=[IO.File]::ReadAllBytes($path)
        try{[IO.File]::WriteAllText($path,'changed',$script:FfdUtf8);$null=Assert-FfdDependencies $io.project $io.output $io.hashes $Budget}finally{[IO.File]::WriteAllBytes($path,$bytes)}
    }
    Invoke-FfdTest $Checks 'dependencies-extra-dll' 'unexpected-output-assembly' {
        $path=Join-Path $io.output 'Unexpected.dll'
        try{[IO.File]::WriteAllText($path,'synthetic',$script:FfdUtf8);$null=Assert-FfdDependencies $io.project $io.output $io.hashes $Budget}finally{[IO.File]::Delete($path)}
    }
    Assert-FfdDeadline $Budget
}
function Invoke-FfdContracts([string] $Dotnet,[string] $Probe,[string] $Root,[string] $Private,[string] $Public,$Budget) {
    $checks=[Collections.Generic.List[object]]::new()
    $testPath=Join-Path $Private 'test-events.jsonl'
    $state=@{now=100000L;local=0.0}
    $tick={ $state.now }.GetNewClosure(); $local={ $state.local }.GetNewClosure()
    $anchor=@{schema='headless-budget-anchor-v1';runId='1';runAttempt='1';jobId='job';tickCount64=100000L;utc='2000-01-01T00:00:00Z'}
    $anchorFile=Join-Path $Private 'contract-budget-anchor.json'
    Invoke-FfdTest $checks 'anchor-file-missing' 'budget-anchor-invalid' {$null=Read-FfdBudgetAnchor $anchorFile '1' '1' 'job' $tick $local}
    Invoke-FfdTest $checks 'anchor-file-corrupt' 'budget-anchor-invalid' {
        [IO.File]::WriteAllText($anchorFile,'{',$script:FfdUtf8);$null=Read-FfdBudgetAnchor $anchorFile '1' '1' 'job' $tick $local
    }
    Write-FfdJson $anchorFile $anchor
    Invoke-FfdTest $checks 'anchor-file-positive' '' {$null=Read-FfdBudgetAnchor $anchorFile '1' '1' 'job' $tick $local}
    Invoke-FfdTest $checks 'anchor-file-extra' 'budget-anchor-invalid' {
        $bad=Copy-FfdTestValue $anchor;$bad.extra=1
        try{Write-FfdJson $anchorFile $bad;$null=Read-FfdBudgetAnchor $anchorFile '1' '1' 'job' $tick $local}finally{Write-FfdJson $anchorFile $anchor}
    }
    $b=New-FfdBudget $anchor '1' '1' 'job' $tick $local
    Invoke-FfdTest $checks 'budget-exact-admission' '' { $state.now=460000L; Assert-FfdBudget $b 540 }
    Invoke-FfdTest $checks 'budget-one-tick-over' 'budget-not-admitted' { $state.now=460001L; Assert-FfdBudget $b 540 }
    Invoke-FfdTest $checks 'budget-clock-backwards' 'budget-anchor-invalid' { $state.now=99999L; Assert-FfdBudget $b 540 }
    $state.now=100000L
    foreach ($field in @('runId','runAttempt','jobId')) {
        Invoke-FfdTest $checks "anchor-wrong-$field" 'budget-anchor-invalid' {
            $bad=$anchor.Clone(); $bad[$field]='other'; $null=New-FfdBudget $bad '1' '1' 'job' $tick $local
        }
    }
    Invoke-FfdTest $checks 'anchor-extra-field' 'schema-fields' { $bad=$anchor.Clone();$bad.extra=1;$null=New-FfdBudget $bad '1' '1' 'job' $tick $local }
    Invoke-FfdTest $checks 'anchor-missing-field' 'schema-fields' { $bad=$anchor.Clone();$bad.Remove('tickCount64');$null=New-FfdBudget $bad '1' '1' 'job' $tick $local }
    foreach ($utc in @('1800-01-01','2800-01-01')) {
        Invoke-FfdTest $checks "utc-irrelevant-$utc" '' { $bad=$anchor.Clone();$bad.utc=$utc;$null=New-FfdBudget $bad '1' '1' 'job' $tick $local }
    }
    Invoke-FfdTest $checks 'budget-late-batch' 'budget-not-admitted' { $state.now=685001L; Assert-FfdBudget $b 315 }
    $state.now=100000L; $state.local=0
    Start-FfdPhase $b 'build' 90 450
    Invoke-FfdTest $checks 'phase-timeout' 'phase-timeout' { $state.local=90001; Assert-FfdDeadline $b }
    Invoke-FfdTest $checks 'reserve-finalization' 'step-timeout' { $state.local=465001; Assert-FfdDeadline $b }
    Invoke-FfdTest $checks 'local-total-timeout' 'step-timeout' { $state.local=480001; Assert-FfdDeadline $b }
    $state.local=0
    Invoke-FfdTest $checks 'events-valid' '' { Write-FfdTestEvents $testPath @(New-FfdTestEvents);$null=Read-FfdEvents $testPath 'synthetic' -Synthetic }
    foreach ($index in @(0,2,5,7,8,10)) {
        Invoke-FfdTest $checks "events-missing-$index" $(if ($index -eq 10) { 'event-incomplete' } else { 'event-identity' }) {
            $ev=@(New-FfdTestEvents); $ev=@($ev | Where-Object { $_.sequence -ne $index })
            Write-FfdTestEvents $testPath $ev; $null=Read-FfdEvents $testPath 'synthetic' -Synthetic
        }
    }
    foreach ($index in @(7,9,11)) {
        Invoke-FfdTest $checks "error-before-after-final-$index" 'event-error' {
            $ev=[Collections.Generic.List[object]]::new(); foreach ($entry in @(New-FfdTestEvents)) { $ev.Add($entry) }
            $ev.Insert($index,@{schema='headless-events-v1';event='error';session='synthetic';sequence=0;data=@{code='synthetic-error'}})
            for($i=0;$i -lt $ev.Count;$i++){$ev[$i].sequence=$i}
            Write-FfdTestEvents $testPath $ev;$null=Read-FfdEvents $testPath 'synthetic' -Synthetic
        }
    }
    Invoke-FfdTest $checks 'duplicate-final' 'event-order' {
        $ev=@(New-FfdTestEvents);$ev[9].event='metrics-final';$ev[9].data=@{status='measured'}
        Write-FfdTestEvents $testPath $ev;$null=Read-FfdEvents $testPath 'synthetic' -Synthetic
    }
    Invoke-FfdTest $checks 'malformed-json' 'json-invalid' { $null=ConvertFrom-FfdJson '{' }
    Invoke-FfdTest $checks 'duplicate-json-field' 'json-duplicate-key' { $null=ConvertFrom-FfdJson '{"x":1,"x":2}' }
    Invoke-FfdTest $checks 'infinite-json' 'invalid-number' { $null=ConvertFrom-FfdJson '{"x":1e999}' }
    Invoke-FfdTest $checks 'negative-duration' 'invalid-number' { Assert-FfdNumber -1 }
    Invoke-FfdTest $checks 'nan-duration' 'invalid-number' { Assert-FfdNumber ([double]::NaN) }
    Invoke-FfdTest $checks 'signed-geometry' '' { Assert-FfdNumber -12.5 -Signed }
    Invoke-FfdTest $checks 'missing-samples' 'sample-set' { $null=Get-FfdAggregate @() }
    Invoke-FfdTest $checks 'process-uncertain-rejected' 'process-incomplete' {
        Assert-FfdProcess @{status='incomplete';started=$true;exitCode=$null;timedOut=$true;logsComplete=$false;termination='uncertain'}
    }
    Invoke-FfdTest $checks 'pipes-open-rejected' 'process-incomplete' {
        Assert-FfdProcess @{status='completed';started=$true;exitCode=0;timedOut=$false;logsComplete=$false;termination='not-needed'}
    }
    Invoke-FfdTest $checks 'ct-source-command-shape' '' {
        Assert-FfdCtCommand @{file='git';arguments=@('status');exitCode=0;timedOut=$false;stdoutBytes=0;stderrBytes=0;complete=$true;termination='not-needed'} $true
    }
    Invoke-FfdTest $checks 'ct-process-command-shape' '' {
        Assert-FfdCtCommand @{file='dotnet';arguments=@();exitCode=0;timedOut=$false;logsComplete=$true;termination='not-needed'} $false
    }
    Invoke-FfdTest $checks 'ct-source-open-pipes' 'ct-process-incomplete' {
        Assert-FfdCtCommand @{file='git';exitCode=0;timedOut=$false;complete=$false;termination='not-needed'} $true
    }
    # Closed -pp grammar fixtures are pure XML; no MSBuild process or engine runs here.
    $rootBanner="<!--`n====================`nC:\repo\probe.csproj`n====================`n-->"
    $openBanner="<!--`n====================`n<Import Project=`"x.props`">`n`nC:\sdk\x.props`n====================`n-->"
    $closeBanner="<!--`n====================`n</Import>`n`nC:\repo\probe.csproj`n====================`n-->"
    $pp="<Project>$rootBanner$openBanner<PropertyGroup><X>1</X></PropertyGroup>$closeBanner</Project>"
    Invoke-FfdTest $checks 'imports-closed-positive' '' {
        $paths=Get-FfdImportInventory $pp
        if($paths.Count -ne 2 -or $paths[1] -cne 'C:\sdk\x.props'){Stop-Ffd 'test-import-paths'}
    }
    foreach($path in @('C:\sdk\x.xml','C:\sdk\x.proj','C:\sdk\noextension')){
        Invoke-FfdTest $checks "imports-unknown-extension-$([IO.Path]::GetFileName($path))" 'import-extension-invalid' {
            $null=Get-FfdImportInventory ($pp.Replace('C:\sdk\x.props',$path))
        }
    }
    foreach($path in @('\\server\share\x.props','/sdk/x.props','relative.props','C:\sdk\..\external\x.props','C:\sdk\$(Injected).props')){
        Invoke-FfdTest $checks 'imports-path-injection' 'import-path-invalid' {
            $null=Get-FfdImportInventory ($pp.Replace('C:\sdk\x.props',$path))
        }
    }
    Invoke-FfdTest $checks 'imports-unrecognized-marker' 'import-boundary-unrecognized' {
        $null=Get-FfdImportInventory '<Project><!-- <Import Project="x.xml"> C:\sdk\x.xml --></Project>'
    }
    Invoke-FfdTest $checks 'imports-opening-omitted' 'import-close-unmatched' {
        $null=Get-FfdImportInventory ($pp.Replace($openBanner,''))
    }
    Invoke-FfdTest $checks 'imports-closing-omitted' 'import-inventory-incomplete' {
        $null=Get-FfdImportInventory ($pp.Replace($closeBanner,''))
    }
    Invoke-FfdTest $checks 'imports-parent-injection' 'import-parent-mismatch' {
        $null=Get-FfdImportInventory ($pp.Replace($closeBanner,$closeBanner.Replace('C:\repo\probe.csproj','C:\other\probe.csproj')))
    }
    Invoke-FfdTest $checks 'imports-extra-path-line' 'import-boundary-unrecognized' {
        $null=Get-FfdImportInventory ($pp.Replace('C:\sdk\x.props',"C:\sdk\x.props`nC:\sdk\other.xml"))
    }
    Invoke-FfdTest $checks 'imports-unexpanded-element' 'unexpanded-import' {
        $null=Get-FfdImportInventory ($pp.Replace('</Project>','<Import Project="x.xml" /></Project>'))
    }
    Invoke-FfdDataContracts $checks $Private $Budget
    # Six synthetic processes TOTAL: vector/codec suite plus five supervisor cases.
    # A single twelve-second aggregate includes their kill confirmation; each <=1 s workload.
    $syntheticWatch=[Diagnostics.Stopwatch]::StartNew()
    $vectorPath=Join-Path $Private 'canonical-vectors.json'
    $vectorProcess=Invoke-FfdProcess $Dotnet @($Probe,'--vectors',$vectorPath) $Root "$Private/vectors" 5 1 $Budget
