    foreach ($name in $literals.Keys) {
        Invoke-FfdTest $checks "literal-$name" '' {
            $matches=@($vectors.vectors | Where-Object { $_.name -ceq $name })
            if ($matches.Count -ne 1) { Stop-Ffd 'vector-missing' }; $v=$matches[0]
            if ($v.hex -cne $literals[$name][0] -or $v.sha256 -cne $literals[$name][1]) { Stop-Ffd 'vector-mismatch' }
            $v.expectedHex=$literals[$name][0];$v.expectedSha256=$literals[$name][1]
            $v['expectedInput']=Read-FfdCanonical ([Convert]::FromHexString($literals[$name][0]))
            $bytes=[Convert]::FromHexString($v.hex)
            if ((Get-FfdBytesHash $bytes) -cne $v.sha256) { Stop-Ffd 'vector-hash' }
            $decoded=Read-FfdCanonical $bytes
            if ($name -ceq 'plus-zero' -and $decoded.bits -cne '00000000') { Stop-Ffd 'vector-zero' }
            if ($name -ceq 'minus-zero' -and $decoded.bits -cne '80000000') { Stop-Ffd 'vector-zero' }
            if ($name -ceq 'e-acute' -and $decoded.value -cne 'é') { Stop-Ffd 'vector-unicode' }
            if ($name -ceq 'structure') {
                if ($decoded.value['boxes'].value.Count -ne 2 -or $decoded.value['dom'].value.Count -ne 2 -or
                    $decoded.value['chunks'].value[0].value['owner'].value -ne $decoded.value['chunks'].value[1].value['owner'].value -or
                    $decoded.value['commands'].value[0].value['values'].value['owner'].value -ne 0) { Stop-Ffd 'vector-structure' }
            }
        }
    }
    foreach ($v in $vectors.vectors) {
        Assert-FfdDeadline $Budget
        $bytes=[Convert]::FromHexString($v.hex)
        if ((Get-FfdBytesHash $bytes) -cne $v.sha256) { Stop-Ffd 'vector-hash' }
        $null=Read-FfdCanonical $bytes
    }
    # Every command primary field is decoded independently, with exactly that field
    # changing. Baselines are full independent literal streams, not encoder output.
    $byName=[Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal)
    foreach($vector in $vectors.vectors){if($byName.ContainsKey($vector.name)){Stop-Ffd 'vector-duplicate'};$byName.Add($vector.name,$vector)}
    foreach($name in $literals.Keys){
        if($name.EndsWith('Command',[StringComparison]::Ordinal)){
            $decoded=Read-FfdCanonical ([Convert]::FromHexString($byName[$name].hex))
            foreach($field in $decoded.value['values'].value.Keys){
                if($field -ceq 'Resource'){
                    if('resource-nonnull' -cnotin $vectors.checks){Stop-Ffd 'resource-negative-missing'};continue
                }
                $mutation="$name.$field"
                if(-not $byName.ContainsKey($mutation)){Stop-Ffd 'field-mutation-missing'}
                $after=Read-FfdCanonical ([Convert]::FromHexString($byName[$mutation].hex))
                Assert-FfdMutation $decoded.value['values'] $after.value['values'] $field
                $checks.Add(@{name="decoded-$mutation";passed=$true})
            }
        } elseif($name.EndsWith('.before',[StringComparison]::Ordinal)){
            $afterName=$name.Substring(0,$name.Length-7)+'.after'
            if(-not $byName.ContainsKey($afterName)){Stop-Ffd 'composite-mutation-missing'}
            $before=Read-FfdCanonical ([Convert]::FromHexString($byName[$name].hex))
            $after=Read-FfdCanonical ([Convert]::FromHexString($byName[$afterName].hex))
            $field=$name.Split('.')[1]
            Assert-FfdMutation $before $after $field
            $checks.Add(@{name="decoded-$afterName";passed=$true})
        }
    }
    if($script:FfdUtf8.GetByteCount(($vectors | ConvertTo-Json -Depth 64 -Compress)) -gt 1MB){Stop-Ffd 'vectors-byte-limit'}
