        }
        if($mode -ceq 'hang'){
            $afterKill={param($process)
                # The real child is killed once. Confirm its exit to avoid an orphan in
                # the test, then inject failure at the supervisor's confirmation seam.
                $injection.confirmedDead=$process.WaitForExit(1000)
                throw [IO.IOException]::new('synthetic confirmation failure')
            }.GetNewClosure()
        }
        $r=Invoke-FfdProcess $Dotnet @($Probe,'--contract',$mode) $Root "$Private/synthetic-$mode" 1 1 $Budget -TestOutputGate $gate -TestAfterKill $afterKill
        $expected=switch($mode){'normal'{'process-timeout'};'nonzero'{'process-nonzero'};'hang'{'process-timeout'};default{'pipe-byte-limit'}}
        $actual=if($null -eq $r.code){''}else{$r.code}
        $checks.Add(@{name="supervisor-$mode";passed=($actual -ceq $expected);expected=$expected;actual=$actual;process=$r})
        if ($actual -cne $expected -or ($mode -cne 'hang' -and $r.termination -ceq 'uncertain')) { Stop-Ffd 'supervisor-test-failed' }
        if($mode -ceq 'hang' -and ($r.termination -cne 'uncertain' -or -not $injection.confirmedDead)){Stop-Ffd 'termination-injection-failed'}
        if($mode -ceq 'normal' -and ($r.logsComplete -or $r.exitCode -ne 0)){Stop-Ffd 'pipe-injection-failed'}
        if ($syntheticWatch.Elapsed.TotalSeconds -gt 12) { Stop-Ffd 'synthetic-budget' }
    }
    Assert-FfdDeadline $Budget
    return [ordered]@{schema='headless-contract-tests-v1';status='passed';checks=$checks.ToArray();syntheticProcesses=6;faultInjection='Pending stdout completion and post-kill confirmation exception; real child death checked by test before simulated uncertainty.';
        syntheticElapsedMs=$syntheticWatch.Elapsed.TotalMilliseconds;engineLoaded=$false;hostConstructed=$false;
        vectorAudit='Independent PowerShell wire decoder and literal byte/hash vectors; no full fixture stream retained.'}
}
